create extension if not exists pgcrypto;
create table if not exists public.artist_content(id integer primary key check(id=1),draft_content jsonb not null default '{}'::jsonb,published_content jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now(),published_at timestamptz,updated_by uuid references auth.users(id) on delete set null);
create table if not exists public.artist_admins(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.artist_content_revisions(id bigint generated always as identity primary key,content jsonb not null,action text not null check(action in ('draft_saved','published','restored')),note text,created_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null);
alter table public.artist_content enable row level security;
alter table public.artist_admins enable row level security;
alter table public.artist_content_revisions enable row level security;
create or replace function public.is_artist_admin() returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.artist_admins where user_id=auth.uid()); $$;
revoke all on function public.is_artist_admin() from public;
grant execute on function public.is_artist_admin() to authenticated;
create or replace function public.get_published_artist_content() returns jsonb language sql stable security definer set search_path=public,pg_temp as $$ select published_content from public.artist_content where id=1; $$;
revoke all on function public.get_published_artist_content() from public;
grant execute on function public.get_published_artist_content() to anon,authenticated;
drop policy if exists "Admin only content access" on public.artist_content;
create policy "Admin only content access" on public.artist_content for all to authenticated using(public.is_artist_admin()) with check(public.is_artist_admin());
drop policy if exists "Admins can read admin list" on public.artist_admins;
create policy "Admins can read admin list" on public.artist_admins for select to authenticated using(public.is_artist_admin());
drop policy if exists "Admins can read revisions" on public.artist_content_revisions;
create policy "Admins can read revisions" on public.artist_content_revisions for select to authenticated using(public.is_artist_admin());
drop policy if exists "Admins can add revisions" on public.artist_content_revisions;
create policy "Admins can add revisions" on public.artist_content_revisions for insert to authenticated with check(public.is_artist_admin());
insert into public.artist_content(id,draft_content,published_content) values(1,'{}'::jsonb,'{}'::jsonb) on conflict(id) do nothing;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('artist-media','artist-media',true,10485760,array['image/jpeg','image/png','image/webp','image/avif','image/gif']) on conflict(id) do update set public=true,file_size_limit=10485760,allowed_mime_types=array['image/jpeg','image/png','image/webp','image/avif','image/gif'];
drop policy if exists "Public can view artist media" on storage.objects;
create policy "Public can view artist media" on storage.objects for select to anon,authenticated using(bucket_id='artist-media');
drop policy if exists "Admins can upload artist media" on storage.objects;
create policy "Admins can upload artist media" on storage.objects for insert to authenticated with check(bucket_id='artist-media' and public.is_artist_admin());
drop policy if exists "Admins can update artist media" on storage.objects;
create policy "Admins can update artist media" on storage.objects for update to authenticated using(bucket_id='artist-media' and public.is_artist_admin()) with check(bucket_id='artist-media' and public.is_artist_admin());
drop policy if exists "Admins can delete artist media" on storage.objects;
create policy "Admins can delete artist media" on storage.objects for delete to authenticated using(bucket_id='artist-media' and public.is_artist_admin());
